pop &lt;- read_excel(file.path(PROJE, "tr_nufus.xlsx")) |&gt;
  rename(year = 1, province_raw = 2, total = 3, male = 4, female = 5) |&gt;
  mutate(
    year = as.integer(year),
    total = num_clean(total),
    male = num_clean(male),
    female = num_clean(female),
    province = normalize_city(province_raw),
    label = PROVINCE_LABELS[province]
  ) |&gt;
  filter(province %in% EQ_KEYS) |&gt;
  arrange(province, year) |&gt;
  group_by(province) |&gt;
  mutate(
    pop_change = total - lag(total),
    pop_change_pct = pop_change / lag(total) * 100,
    sex_ratio = male / female * 100
  ) |&gt;
  ungroup()

damage &lt;- read_excel(file.path(PROJE, "deprem_hasar_tablosu.xlsx")) |&gt;
  clean_names() |&gt;
  rename(
    province_raw = il,
    heavy = toplam_agir_yikik_konut_sayisi,
    medium = orta_hasarli_konut_sayisi,
    light = az_hasarli_konut_sayisi
  ) |&gt;
  filter(!is.na(province_raw), province_raw != "Bölge Toplam") |&gt;
  mutate(
    province = normalize_city(province_raw),
    heavy = num_clean(heavy),
    medium = num_clean(medium),
    light = num_clean(light),
    total_damage = heavy + medium + light
  ) |&gt;
  filter(province %in% EQ_KEYS) |&gt;
  left_join(
    pop |&gt; filter(year == 2022) |&gt; select(province, pop_2022 = total),
    by = "province"
  ) |&gt;
  mutate(
    heavy_per_1000 = heavy / pop_2022 * 1000,
    medium_per_1000 = medium / pop_2022 * 1000,
    light_per_1000 = light / pop_2022 * 1000,
    total_damage_per_1000 = total_damage / pop_2022 * 1000,
    label = PROVINCE_LABELS[province]
  )

flows_2023 &lt;- read_excel(
  file.path(PROJE, "deprem_2023_goc_akislari_duzenlenmis.xlsx"),
  sheet = "Flow_2023_All"
) |&gt;
  clean_names() |&gt;
  transmute(
    from = normalize_city(origin_province),
    to = normalize_city(destination_province),
    value = num_clean(migration_count)
  ) |&gt;
  filter(from %in% EQ_KEYS, value &gt; 0)

mig_raw &lt;- read_excel(file.path(PROJE, "deprem_goc_ham_filtreli.xlsx"), skip = 2) |&gt;
  clean_names() |&gt;
  filter(!is.na(yil)) |&gt;
  transmute(
    year = as.integer(yil),
    dest = normalize_city(goc_alan_il_adi),
    origin = normalize_city(goc_veren_il_adi),
    flow = num_clean(aldigi_goc)
  )

net_migration &lt;- bind_rows(
  mig_raw |&gt; transmute(year, province = dest, inflow = flow, outflow = 0),
  mig_raw |&gt; transmute(year, province = origin, inflow = 0, outflow = flow)
) |&gt;
  filter(province %in% EQ_KEYS) |&gt;
  group_by(year, province) |&gt;
  summarise(
    inflow = sum(inflow, na.rm = TRUE),
    outflow = sum(outflow, na.rm = TRUE),
    net_migration = inflow - outflow,
    .groups = "drop"
  ) |&gt;
  left_join(pop |&gt; select(year, province, total), by = c("year", "province")) |&gt;
  mutate(
    net_migration_rate = net_migration / total * 1000,
    label = PROVINCE_LABELS[province]
  )

analysis_data &lt;- pop |&gt;
  filter(year %in% c(2022, 2023)) |&gt;
  select(province, label, year, total) |&gt;
  pivot_wider(names_from = year, values_from = total, names_prefix = "pop_") |&gt;
  mutate(
    pop_change = pop_2023 - pop_2022,
    pop_change_pct = pop_change / pop_2022 * 100
  ) |&gt;
  left_join(
    damage |&gt; select(province, heavy_per_1000, total_damage_per_1000),
    by = "province"
  )

cover_stats &lt;- tibble(
  net_loss_2023 = net_migration |&gt;
    filter(year == 2023) |&gt;
    summarise(x = sum(net_migration, na.rm = TRUE)) |&gt;
    pull(x),
  affected_provinces = length(EQ_KEYS),
  period_years = max(pop$year, na.rm = TRUE) - min(pop$year, na.rm = TRUE) + 1
)

save(
  pop, damage, flows_2023, net_migration, analysis_data,
  file = file.path(PROJE, "final_earthquake_migration_project.RData")
)
