library(tidyverse)
library(readxl)
library(janitor)
library(sf)
library(htmltools)
library(stringi)
library(geojsonsf)

normalize_city &lt;- function(x) {
  x %&gt;%
    str_to_upper(locale = "tr") %&gt;%
    stringi::stri_trans_general("Latin-ASCII") %&gt;%
